function makeSprite(c,isEnemy=false){const canvas=document.createElement('canvas');canvas.width=72;canvas.height=96;const x=canvas.getContext('2d');x.imageSmoothingEnabled=false;const px=6,p=(a,b,w,h,col)=>{x.fillStyle=col;x.fillRect(a*px,b*px,w*px,h*px)},outline='#171a26',skin='#e9b99a',cloth=c.color,dark='#303044',gold='#e9c66e';p(4,14,4,1,outline);p(3,13,6,2,outline);p(3,7,6,6,outline);p(4,8,4,4,skin);p(4,10,1,1,dark);p(7,10,1,1,dark);p(4,7,4,1,c.id==='mage'?'#d3baff':'#503c3b');p(3,6,6,2,outline);p(4,6,4,1,c.id==='rogue'?'#34394d':'#4c3b48');p(2,14,8,1,outline);p(3,14,6,4,cloth);p(4,14,4,1,gold);p(4,15,1,2,outline);p(7,15,1,2,outline);p(2,15,1,3,outline);p(9,15,1,3,outline);p(3,18,2,2,dark);p(7,18,2,2,dark);p(2,20,3,1,outline);p(7,20,3,1,outline);if(c.id==='guard'){p(0,14,2,5,outline);p(0,15,2,3,'#9aaac7');p(10,12,1,7,outline);p(11,10,1,4,gold)}if(c.id==='mage'){p(4,4,4,1,'#6b4c91');p(5,2,2,3,outline);p(5,2,2,2,'#ac8cf1');p(10,8,1,8,outline);p(10,7,1,1,gold)}if(c.id==='ranger'){p(1,11,1,8,outline);p(1,11,1,6,'#a5cf8b');p(10,11,1,7,gold);p(9,14,3,1,outline)}if(c.id==='cleric'){p(5,3,2,1,gold);p(5,2,2,3,gold);p(4,3,4,1,gold);p(10,13,1,7,outline);p(10,12,1,1,gold)}if(c.id==='rogue'){p(3,7,6,2,'#383d51');p(10,15,2,1,outline);p(11,13,1,3,'#d7e0ef')}if(c.id==='druid'){p(3,6,1,2,'#83ba76');p(8,5,1,3,'#83ba76');p(10,12,1,8,outline);p(10,11,1,2,'#9a724c')}if(c.id==='brawler'){p(1,14,2,2,outline);p(1,14,2,2,'#f1bd86');p(9,14,2,2,outline);p(9,14,2,2,'#f1bd86')}if(c.id==='bard'){p(4,6,1,1,'#e6ce6b');p(8,6,1,1,'#e6ce6b');p(10,14,1,5,outline);p(10,13,2,2,'#c38b5d')}if(isEnemy){x.fillStyle='#ed7072';x.globalAlpha=.23;x.fillRect(0,0,72,96);x.globalAlpha=1}return canvas.toDataURL()}
function entity(u,side){const c=klass(u.classId),a=acc(u.accId);return {...u,side,c,a,maxHp:c.hp+a.hp,hp:c.hp+a.hp,atk:c.atk+a.atk,def:c.def+a.def,acted:false,guarding:false,attackBoost:0,alive:true}}
function startBattle(){if(team.length!==5)return;document.getElementById('builderScreen').classList.add('hide');document.getElementById('battleScreen').classList.add('show');document.querySelectorAll('.step')[1].classList.add('active');let used={};enemy=Array.from({length:5},(_,i)=>{const c=CLASSES[Math.floor(Math.random()*CLASSES.length)],ix=used[c.id]||0;used[c.id]=ix+1;return entity({uid:`e${i}`,classId:c.id,name:NAMES[c.id][(ix+1)%3],accId:ACCESSORIES[Math.floor(Math.random()*ACCESSORIES.length)].id},'enemy')});team=team.map(u=>entity(u,'ally'));round=1;turn='player';guarded=[];gameOver=false;selectedId=null;targetMode=null;document.getElementById('battleLog').innerHTML='';log(`¡Comienza la batalla! ${team.length} campeones contra ${enemy.length} rivales.`);renderBattle();selectAlly(team.find(x=>x.alive))}document.getElementById('startBtn').onclick=startBattle;
let targetMode=null;
function spriteHTML(u,side){return `<img src="${makeSprite(u.c,side==='enemy')}" alt="">`}
function renderBattle(){for(const [list,where,side] of [[team,'allySide','ally'],[enemy,'enemySide','enemy']])document.getElementById(where).innerHTML=list.map(u=>`<div class="fighter ${side==='enemy'?'enemy':''} ${u.alive?'':'dead'} ${u.uid===selectedId?'active':''} ${side==='enemy'&&targetMode?'selected-target':''}" data-unit="${u.uid}" data-side="${side}"><div class="fighter-sprite">${spriteHTML(u,side)}</div><div class="fighter-info"><div class="fighter-name">${u.name}</div><div class="hp-track"><div class="hp-fill ${u.hp/u.maxHp<.3?'low':''}" style="width:${Math.max(0,u.hp/u.maxHp*100)}%"></div></div><div class="fighter-hp">${Math.max(0,u.hp)} / ${u.maxHp}</div></div></div>`).join('');document.querySelectorAll('.fighter').forEach(el=>el.onclick=()=>{const u=[...team,...enemy].find(x=>x.uid===el.dataset.unit);if(!u?.alive||turn!=='player'||gameOver)return;if(el.dataset.side==='ally'){if(!u.acted)selectAlly(u)}else if(targetMode)resolveTarget(u)});const alive=team.filter(u=>u.alive),foes=enemy.filter(u=>u.alive),active=team.find(u=>u.uid===selectedId);document.getElementById('roundPill').textContent=`RONDA ${round} · TURNO ${turn==='player'?'ALIADO':'RIVAL'}`;document.getElementById('logRound').textContent=`R${round}`;document.getElementById('turnBanner').textContent=gameOver?'COMBATE FINALIZADO':turn==='enemy'?'LOS RIVALES ATACAN':targetMode==='attack'?'ELIGE UN RIVAL':targetMode==='skill'?'ELIGE EL OBJETIVO':turn==='player'?'ELIGE UN CAMPEÓN Y SU ACCIÓN':'RESOLVIENDO…';document.getElementById('attackBtn').disabled=!active||turn!=='player'||gameOver||active.acted;document.getElementById('skillBtn').disabled=!active||turn!=='player'||gameOver||active.acted;document.getElementById('activeIcon').textContent=active?active.c.icon:'⚔️';document.getElementById('activeName').textContent=active?`${active.name} · ${active.c.name}`:'Elige un aliado';document.getElementById('activeSub').textContent=active?`${active.c.role}  ·  ${active.hp}/${active.maxHp} PV  ·  ${active.a.icon} ${active.a.name}`:'Pulsa un campeón vivo';document.getElementById('skillLabel').textContent=active?active.c.skill:'Habilidad';document.getElementById('skillHint').textContent=active?active.c.skillDesc.toUpperCase():'ÚNICA DE CLASE';document.getElementById('actionHelp').textContent=targetMode?'Ahora elige un rival en la arena.':turn==='player'&&active?`${alive.filter(x=>!x.acted).length} aliado(s) aún pueden actuar.`:'Selecciona uno de tus campeones para ver sus acciones.';document.getElementById('attackBtn').querySelector('.action-hint').textContent=active&&foes.length?`~${Math.max(3,active.atk-foes[0].def+1)} DAÑO`:'DAÑO ESTABLE'}
function selectAlly(u){selectedId=u?.uid||null;targetMode=null;renderBattle()}function log(text){const box=document.getElementById('battleLog');if(!box)return;box.insertAdjacentHTML('afterbegin',`<div>› ${text}</div>`);while(box.children.length>24)box.lastElementChild.remove()}function hurt(t,raw,ignoreDef=false){if(!t.alive)return 0;const dmg=Math.max(2,raw-(ignoreDef?0:t.def)-(t.guarding?8:0));t.hp=Math.max(0,t.hp-dmg);if(!t.hp){t.alive=false;log(`${t.name} cae derrotado.`)}return dmg}function floatText(uid,text,color){const el=document.querySelector(`[data-unit="${uid}"]`);if(!el)return;const d=document.createElement('div');d.className='floating';d.style.color=color;d.textContent=text;el.appendChild(d);setTimeout(()=>d.remove(),850);el.classList.add('strike');setTimeout(()=>el.classList.remove('strike'),250)}function doAttack(attacker,target,raw=attacker.atk,ignore=false){const dmg=hurt(target,raw+attacker.attackBoost,ignore);floatText(target.uid,`−${dmg}`,'#ff8b7f');log(`${attacker.name} golpea a ${target.name} por ${dmg} de daño.`)}function chooseTargetMode(m){targetMode=m;renderBattle()}document.getElementById('attackBtn').onclick=()=>{if(selectedId)chooseTargetMode('attack')};document.getElementById('skillBtn').onclick=()=>useSkill();
function weakest(list){return list.filter(x=>x.alive).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0]}function healAll(amount){team.filter(x=>x.alive).forEach(t=>{const n=Math.min(amount,t.maxHp-t.hp);t.hp+=n;if(n)floatText(t.uid,`+${n}`,'#8be0b1')})}
function useSkill(){const u=team.find(x=>x.uid===selectedId);if(!u||u.acted||turn!=='player')return;const s=u.c.special;if(['snipe','double','pierce'].includes(s)){chooseTargetMode('skill');return}if(s==='guard'){u.guarding=true;guarded.push(u.uid);log(`${u.name} alza su Muro de hierro y provoca a los rivales.`);floatText(u.uid,'DEFENSA ↑','#9dc0ff')}if(s==='aoe'){enemy.filter(x=>x.alive).forEach(t=>doAttack(u,t,Math.round(u.atk*.72)));log(`${u.name} desata una lluvia arcana sobre todos.`)}if(s==='heal'){healAll(24);log(`${u.name} invoca Luz reparadora para todo el equipo.`)}if(s==='balance'){const t=team.filter(x=>x.alive).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(t){const n=Math.min(23,t.maxHp-t.hp);t.hp+=n;floatText(t.uid,`+${n}`,'#8be0b1');log(`${u.name} cura ${n} PV a ${t.name}.`)}const foe=weakest(enemy);if(foe)doAttack(u,foe,Math.round(u.atk*.75))}if(s==='buff'){team.filter(x=>x.alive).forEach(t=>t.attackBoost+=4);log(`${u.name} toca un Himno de guerra. ¡Todo el equipo gana +4 ATQ!`);floatText(u.uid,'ATQ ↑','#edc568')}u.acted=true;finishAction()}
function resolveTarget(target){const u=team.find(x=>x.uid===selectedId);if(!u||!target.alive)return;targetMode=null;const s=u.c.special;if(s==='snipe'){doAttack(u,target,Math.round(u.atk*1.65));log(`${u.name} acierta un Disparo certero crítico.`)}else if(s==='double'){doAttack(u,target,Math.round(u.atk*.78));if(target.alive)doAttack(u,target,Math.round(u.atk*.78));log(`${u.name} aparece tras ${target.name} con un Golpe furtivo.`)}else if(s==='pierce'){doAttack(u,target,Math.round(u.atk*1.5),true);log(`${u.name} descarga un Puño sísmico que ignora defensa.`)}else doAttack(u,target);u.acted=true;finishAction()}
function finishAction(){renderBattle();if(checkEnd())return;if(team.every(x=>!x.alive||x.acted)){setTimeout(enemyPhase,500)}else selectAlly(team.find(x=>x.alive&&!x.acted))}function checkEnd(){if(!enemy.some(x=>x.alive)){gameOver=true;showResult(true);return true}if(!team.some(x=>x.alive)){gameOver=true;showResult(false);return true}return false}

