document.getElementById('againBtn').onclick=()=>{document.getElementById('resultModal').classList.remove('show');document.getElementById('battleScreen').classList.remove('show');document.getElementById('builderScreen').classList.remove('hide');document.querySelectorAll('.step')[1].classList.remove('active');team=[];enemy=[];renderTeam()};document.getElementById('backBtn').onclick=()=>{if(turn==='enemy'||gameOver)return;document.getElementById('battleScreen').classList.remove('show');document.getElementById('builderScreen').classList.remove('hide');document.querySelectorAll('.step')[1].classList.remove('active');team=team.map(u=>({uid:u.uid,classId:u.classId,name:u.name,accId:u.accId}));renderTeam()};renderTeam();
</script></body></html>

