 function enemyPhase(){if(gameOver)return;turn='enemy';targetMode=null;selectedId=null;renderBattle();const actors=enemy.filter(x=>x.alive);let i=0;function next(){if(gameOver||checkEnd())return;if(i>=actors.length){round++;team.forEach(x=>{x.acted=false;x.guarding=false});enemy.forEach(x=>x.guarding=false);turn='player';guarded=[];log(`Ronda ${round}. ¡Tu equipo toma la iniciativa!`);renderBattle();selectAlly(team.find(x=>x.alive));return}const actor=actors[i++];if(!actor.alive){setTimeout(next,350);return}const live=team.filter(x=>x.alive);if(!live.length){checkEnd();return}let target=guarded.map(id=>team.find(x=>x.uid===id&&x.alive)).find(Boolean)||live[Math.floor(Math.random()*live.length)];if(actor.c.special==='heal'&&Math.random()<.22){const friend=weakest(enemy);const n=Math.min(18,friend.maxHp-friend.hp);friend.hp+=n;if(n)floatText(friend.uid,`+${n}`,'#8be0b1');log(`${actor.name} usa ${actor.c.skill} y cura ${n} PV a ${friend.name}.`)}else if(actor.c.special==='aoe'&&Math.random()<.3){team.filter(x=>x.alive).forEach(t=>{const d=hurt(t,Math.round(actor.atk*.55));floatText(t.uid,`−${d}`,'#ff8b7f')});log(`${actor.name} lanza ${actor.c.skill} contra todo el equipo.`)}else doAttack(actor,target,actor.atk+Math.floor(Math.random()*4)-1);renderBattle();if(checkEnd())return;setTimeout(next,650)}next()}
 function showResult(win){document.getElementById('resultSymbol').textContent=win?'🏆':'💀';document.getElementById('resultTitle').textContent=win?'¡Victoria!':'Derrota';document.getElementById('resultText').textContent=win?`Tu escuadrón venció a los rivales en ${round} ronda${round===1?'':'s'}. La leyenda de tus campeones apenas comienza.`:'Los rivales dominaron la arena. Cambia tus accesorios o prueba otra formación y vuelve a luchar.';document.getElementById('resultModal').classList.add('show')}
